// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 06 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd155476": "Его зовут Брайан, и он — фанатик турбин и нитроускорителей. Его цель — быть принятым в автобанду легендарного Доминика Торетто, чемпиона опасных и незаконных уличных гонок. Но это лишь часть правды… Брайан также полицейский, имеющий задание войти в доверие к Торетто, подозреваемому в причастности к дерзким грабежам трейлеров, совершенным прямо «с колес».Но чем больше доверяет нахальному новичку харизматичный Доминик, тем больше проникается герой идеалами «ангелов дорог». И тем меньше ему хочется выполнять свою миссию. И вот, наступает момент, когда Брайану придется выбирать между дружбой и долгом. И выбирать на скорости в 200 километров в час…",
 "f-wd488655": "Телевизионный комментатор Фил Коннорс каждый год приезжает в маленький городок в штате Пенсильвания на празднование Дня сурка. Но на этот раз веселье рискует зайти слишком далеко. Время сыграло с ним злую шутку: оно взяло да и остановилось. Теперь на календаре Фила чернеет одна и та же дата - 2 февраля, из которой он никак не может выбраться. Неунывающий ведущий пытается извлечь выгоду из своего комичного положения: впереди у него уйма времени и безмятежное предсказуемое будущее. Отныне с ним не случится ничего плохого... и ничего хорошего. У Фила осталась одна заветная мечта, простая и незамысловатая - 3 февраля...",
 "f-wd105105219": "Рид Ричардс, Бен Гримм, Сью Сторм и её брат Джонни должны защитить Землю от космического бога Галактуса и его приспешника — Серебряного Сёрфера. И если план Галактуса поглотить всю планету и всех её жителей кажется недостаточно ужасающим, ситуация внезапно становится личной.",
 "f-wd20501835": "Вдохновившись самопожертвованием Супермена, Брюс Уэйн вновь обретает веру в человечество. Он заручается поддержкой новой союзницы Дианы Принс, чтобы сразиться с ещё более могущественным противником. Бэтмен и Чудо-Женщина быстро набирают команду сверхлюдей для борьбы с пробудившейся угрозой. Но, несмотря на уникальный состав отряда супергероев — Бэтмен, Чудо-Женщина, Аквамен, Киборг и Флэш, — быть может, спасать планету от вторжения катастрофических масштабов уже слишком поздно.",
 "f-wd23010088": "Питер Паркер - обычный школьник из Нью-Йорка, который после укуса генетически изменённого паука получает сверхспособности и становится Человеком-пауком. Под маской он защищает жителей города, используя невероятную силу, ловкость и способность цепляться за стены, а также созданные им веб-шутеры для перемещения между зданиями. После встречи с Тони Старком, Питер получает новый высокотехнологичный костюм и пытается доказать, что способен стать настоящим супергероем. Однако появление опасного преступника Стервятника превращает его обычную жизнь в серьёзное испытание, где Питеру предстоит одновременно оставаться школьником и Человеком-пауком.",
 "f-wd54860489": "После смерти короля Т`Чаллы королева Рамонда, Шури, М`Баку, Окойе и Накия сражаются, чтобы защитить Ваканду от мировых держав.",
 "f-wd55436290": "Барбилэнд — идеальное место для всех, кто идеален. Но что делать, если у тебя случился экзистенциальный кризис? Барби и Кен отправляются навстречу приключениям в реальный мир.",
 "f-wd645735": "Вена. Начало 20 века. В городе появляется загадочный человек, называвший себя иллюзионистом Эйзенхаймом. Он показывает публике невиданные фокусы, которые кажутся не иначе как волшебством. Слава о необыкновенном чародее доходит до кронпринца Леопольда, который почтил своим присутствием одно из представлений Эйзенхайма. Леопольда сопровождает его будущая невеста Софи. Её появление в зале дает толчок для целой вереницы необъяснимых событий, корни которых уходят в прошлое…",
 "f-wd209481": "Билл и Элис Харфорд — супружеская пара, производящая впечатление счастливых людей, живущих своей размеренной жизнью в полном достатке. Но за фасадом идеальных отношений скрываются потоки ревности, неудовлетворённости, тайных желаний и жажды чего-то запредельного.\r Первый шаг делает Элис, рассказывая мужу о своих фантазиях. Терзаемый ревностью Билл идет дальше, выходя за рамки мыслей и слов. Он наяву отправляется в пьянящую сексуальную одиссею, ведомый соблазном и щекочущими нервы переживаниями. Если бы в начале пути он знал, что пределом его мечтаний станет возможность вернуться к своей привычной семейной жизни, он бы не поверил, ведь искушение вкусить запретный плод было слишком сильно…",
 "f-wd2140247": "Расселл Прайс воспринимает революцию в Никарагуа через камеру, чтобы дистанцироваться от реальности. В Манагуа его эмоциональная отрешенность от происходящего подвергается испытанию, когда он видит резкий контраст между жизнью сторонников президента Сомосы и тем, что приходится переносить всем остальным в стране…",
 "f-wd52000412": "Коллектив танцоров устраивает трехдневные репетиции в закрытой школе, расположенной в самом центре леса. Они начинают выпивать, однако уже скоро каждый из них испытывает взрыв эмоций, который явно отличается от обычного опьянения. Танцоры перестают сопротивляться своим неврозам и психозам, отдаваясь ритмам музыки. В то время, как некоторые оказываются в раю, другие попадают в ад.",
 "f-wd30611924": "Олегу нет и тридцати. Он талантливый врач, работает на «скорой», которая мчится от пациента к пациенту. Олег знает: его приезд может изменить всё. Каждый его успех делает мир лучше. Самое важное — там, где он пытается совершить невозможное. А остальное может подождать: семья, карьера, своя жизнь… Что с ней случилось?  Пока Олег спасал других, жена отчаялась и решила подать на развод, а в больнице появился новый начальник, который печется только о статистике и правилах. А Олег все спешит с вызова на вызов, несется по улице, чтобы всё изменить. И кто знает, какая задача легче: спасать других или спасти себя?",
 "f-wd30726990": "Полицейскому, которого перевели в полицию Марселя, поручают непростое задание - ему нужно поймать банду итальянских грабителей, которые используют в налетах автомобили Феррари. А помогать ему в этом будет племянник Даниэля...",
 "f-wd27198272": "XIII век. Русь раздроблена и вот-вот падет на колени перед ханом Золотой Орды Батыем. Испепеляя города и заливая русские земли кровью, захватчики не встречают серьезного сопротивления, и лишь один воин бросает им вызов. Молодой рязанский витязь Евпатий Коловрат возглавляет отряд смельчаков, чтобы отомстить за свою любовь и за свою родину. Его отвага поразит даже Батыя, а его имя навсегда останется в памяти народа. Воин, ставший легендой. Подвиг, сохранившийся в веках.",
 "f-wd25339558": "Отношения молодой пары оказываются под угрозой, когда, нарушая безмятежное существование супругов, в их дом заявляются незваные гости.",
 "f-wd15624215": "Еще вчера она была просто сексапильной блондинкой, а сегодня - самое опасное и смертоносное создание на планете со сверхъестественными способностями и интеллектом. То, что совсем недавно лучшие умы мира считали фантастической теорией, для нее стало реальностью. И теперь из добычи она превратится в охотницу.",
 "f-wd4376921": "Действие фильма разворачивается в течение полутора-двух часов в одной комнате, где проходит не совсем обычное заседание парткома строительного треста. В повестке дня — отказ целой бригады строителей от премии за «липовые» трудовые достижения!",
 "f-wd65154498": "Лето 1944 года. Советские войска ведут наступление, но враг еще очень силен. Летчик-истребитель Михаил Девятаев попадает в плен. Ему предстоит сделать выбор - вернуться в небо, продолжив войну на стороне врага, или отправиться в концлагерь на остров Узедом. Отчаянный ас Девятаев выбирает третье - побег. Но с засекреченного острова, где идут испытания немецких крылатых ракет, нельзя убежать. Зато можно улететь - на аэродроме стоит новейший вражеский бомбардировщик с «оружием возмездия» Третьего рейха на борту. Улететь - и совершить самый дерзкий побег в военной истории.",
 "f-wd28667179": "Москва 2070 год. Мир лежит в руинах после ядерной войны. Выживание человечества зависит от энергии, которую отдают участники жестокого танцевального турнира. Но когда один из претендентов влюбляется в девушку, участницу состязания, и решает любой ценой спасти её жизнь, отлаженная система оказывается под угрозой.",
 "f-wd4478935": "Своей искалеченной судьбой заплатил комдив Котов за восстановление доброго имени. Он возвращается в дом, воспоминания о котором давали ему силы все эти страшные годы. Но то, что ждало в этом доме, его потрясло. Все изменилось, его хрупкий мир рухнул. Котову снова придется сражаться. За свое имя, за свою честь, за свою любовь, за свою Цитадель…",
 "f-wd22957393": "Скотт Лэнг, известный также, как Человек-Муравей уже заслужил право оказаться в команде Мстителей, но желание быть ближе к собственной дочке удерживает его в родном Сан-Франциско — до тех пор, пока доктор Хэнк Пим, создавший когда-то изменяющий размеры своего владельца чудо-костюм, не призывает Скотта присоединиться к новой, опасной миссии. А помогать в противостоянии с коварным врагом Человеку-Муравью будет новая напарница — Оса.",
 "f-wd119821866": "Пять лет назад адский клоун-маньяк Арт восстал из мёртвых, выкрал из психлечебницы Викторию и заснул. А Сиенна, проведя эти годы в специализированном учреждении, собирается встретить Рождество с семьёй тёти. Она обожает младшую двоюродную сестру и рада находиться в кругу родни, но страшные видения не отпускают девушку. Как раз в это время незадачливые рабочие пробуждают Арта и демона, вселившегося в изуродованное тело Виктории, — так порождения тьмы отправляются наводить рождественскую суету среди ничего не подозревающих жителей округа Майлз.",
 "f-wd922193": "Когда Ослик Ушастик теряет свой хвост, Филин отправляет друзей (Винни, Тигрулю, Кролика, Хрюню, Кенгу и Крошку Ру) помочь бедолаге найти пропажу, а заодно — спасти Кристофера Робина от таинственного Яскорра. А ведь медвежонок Винни, собирался всего лишь отыскать где-нибудь немного мёда, чтобы слегка подкрепиться, и даже не предполагал, что его ждёт такой суматошный день!",
 "f-wd105584511": "Пригород Денвера, 1978 год. Уже некоторое время в округе пропадают подростки, но 13-летний Финн больше обеспокоен тем, чтобы не столкнуться со школьными хулиганами и не разозлить вспыльчивого отца. Единственный человек, который его понимает, — это младшая сестра. Но однажды Финн всё же попадает в лапы маньяка и приходит в себя в звуконепроницаемом подвале. Кажется, надежды на спасение нет, но вскоре по отключенному телефону парню начинают звонить предыдущие жертвы убийцы.",
 "f-wd32067466": "Слендермен — это худощавая фигура в похоронном костюме, без лица, без красок и без ясных намерений. Он становится кошмаром множества детей и подростков, которые пытаются укрыться от его преследования, пока однажды не исчезают без следа.",
 "f-wd166355": "Судьба сводит героев картины в больнице, где врачи выносят им смертный приговор. Счёт времени их жизней идёт на часы. Дальнейшие события в фильме разворачиваются в стремительном темпе. Украв машину с миллионом немецких марок в багажнике, они сбегают из больницы. Их преследуют наёмные убийцы, они становятся грабителями поневоле, за ними гонится полиция, они попадают в бордель. Но тем не менее продолжают мчаться вперёд, навстречу своей Судьбе.",
 "f-wd116971304": "Два агента высшей квалификации сближаются, когда их назначают охранять противоположные стороны загадочного ущелья. Зло, таящееся на дне ущелья, вырывается наружу, и они должны объединиться, чтобы выжить.",
 "f-wd123690368": "Двоюродные братья Дэвид и Бенджи, которые не виделись какое-то время, отправляются в тур по Польше, чтобы почтить память любимой бабушки. Однако накопленные за долгие годы обиды и противоречия постепенно дают о себе знать.",
 "f-wd107175474": "Спустя шесть месяцев после начала одиночной миссии астронавт пытается справиться с проблемами в своем браке при помощи обнаруженного им на корабле мистического существа.",
 "f-wd114818951": "Покончив с работой тайного агента Роберт Макколл продолжает отстаивать правду в повседневной жизни и защищать тех, кто в этом нуждается. Находясь в Южной Италии он узнает, что его друзья оказались под влиянием местных криминальных авторитетов. Когда события обостряются, Макколл решает встать на защиту справедливости, вступив в борьбу с мафией.",
 "f-wd63842704": "Что происходит в сказках после свадьбы принца и принцессы? Фигуристка Надя и хоккеист Саша поженились и больше всего на свете мечтают о ребёнке. Правда, цена, которую им придётся заплатить за эту мечту, будет невообразимо высока. Кажется, что после таких потрясений рассчитывать на счастливый конец уже невозможно. Но если вы так думаете, вы ничего не знаете о настоящих сказках...",
 "f-wd113524284": "После гибели техногенной цивилизации в мир вернулись магия и монстры. По тайному заданию королевы ведьма Серая Элис отправляется из последнего города Земли в опасные Потерянные земли. Вместе с проводником Бойсом ей предстоит до полной Луны найти источник силы, что может обращать человека в зверя. Путников преследует безжалостная армия крестоносцев, а за каждым поворотом поджидают порождения тьмы.",
 "f-wd172284": "Трогательная и захватывающая история сближения двух абсолютно разных собак — породистой комнатной неженки и бездомного дворняги. Изящная и пушистая как игрушка, коккер-спаниельша Леди была любимицей хозяев, пока в их семье не появился младенец. Надетый намордник стал последней каплей, подтолкнувшей обиженную героиню к бегству.  Но на улице ее поджидала целая куча опасностей, о существовании которых она даже не подозревала. И тогда на помощь миниатюрной черноглазой красотке пришел разбитной пес Бродягя, благородство которого было не в породе, а в душе.  Проявив отзывчивость и мужество, он в конце концов завоевал сердце нежной Леди.",
 "f-wd102225": "Гарри Поттер, Рон и Гермиона возвращаются на четвёртый курс школы чародейства и волшебства «Хогвартс». При таинственных обстоятельствах Гарри отобран в число участников опасного соревнования — Турнира Трёх Волшебников, однако проблема в том, что все его соперники — намного старше и сильнее. К тому же, знаки указывают на возвращение Лорда Волдеморта. Вскоре Гарри предстоит побороться не только за победу в соревновании, но и, прежде всего, за свою жизнь...",
 "f-wd187266": "Ковбой Вуди и другие игрушки мальчика Энди продолжают жить, радуясь каждому дню. Но неожиданно всё меняется, когда Вуди похищает коварный коллекционер. Оказывается, что Вуди - очень ценная игрушка из коллекции, за которую японский музей игрушек готов заплатить огромную сумму. В доме коллекционера он находит своих родственников. В это время игрушки во главе с Баззом Лайтером отправляются на помощь. Вуди узнаёт о своём знаменитом прошлом, и перед ним встаёт непростой выбор. Блистать в витрине музея или же вернуться к любимому хозяину?",
 "f-wd537407": "Для великого народа наступили тяжелые времена: на страну напало воинственное племя гуннов. Переодевшись в мужскую одежду, Мулан присоединяется к другим воинам и отправляется в опасный поход к подножию заснеженных гор. Ее сопровождает забавный дракончик Мушу, который больше похож на маленькую собачку, чем на мифическое чудовище.Пытаясь скрыть тайну, они попадают в забавные ситуации и не подозревают, что их секрет вот — вот раскроется!…",
 "f-wd160618": "Между двумя пастухами в Вайоминге в 1963 году завязывается все более страстный роман. Но встречаться втайне, скрывая отношения от жен, становится нестерпимо больно.",
 "f-wd943192": "Необычайный, поражающий воображение мультконцерт, небывалое ранее единение музыки и мультипликации. Дисней и знаменитый дирижер Леопольд Стоковски решили воспроизвести на экране фантазии, возникающие в сознании людей при прослушивании музыкальных шедевров.Картина состоит из 8 классических композиций, проиллюстрированных сюжетными инсценировками и ритмичными абстракциями, предвосхищающими чудеса компьютерной графики.",
 "f-wd213787": "Юная цыганка Эсмеральда зарабатывает на жизнь танцами. У нее есть друзья, но недоброжелатели столь могущественны, что Эсмеральда попадает в тюрьму. Звонарь Квазимодо устраивает девушке побег. А потом спасает ее, когда ослепленный ненавистью епископ Фролло пытается сам расправиться с ней. Этот мультфильм, в отличии от известного романа В. Гюго, кончается счастливо для главных героев.",
 "f-wd270470": "Уолт Дисней зовет нас с собой в волшебную страну Неверленд, где живет удивительный мальчик, который умеет летать и отказывается взрослеть. Это веселый выдумщик, храбрец и проказник Питер Пэн!Однажды в поисках собственной тени Питер попадает в Лондон нашего мира и становится другом маленькой Венди и ее братьев Майкла и Джона, и, конечно же, он берет своих ночных друзей с собой в Неверленд, навстречу потрясающим приключениям.Героям предстоит встретиться с феей Тинкербелл и дружной ватагой Питера Пэна, спасти индейскую принцессу Тигровую Лилию из лап пиратов и сразиться с их демоническим главарем капитаном Крюком!..",
 "f-wd28891": "Ральф — второстепенный персонаж восьмибитной компьютерной игры, и ему надоело находиться в тени главного героя, мастера на все руки Феликса, который всегда появляется, чтобы «исправить» ситуацию! После тридцати лет добросовестной работы в роли злодея, в течение которых все похвалы выпадали на долю Феликса, Ральф больше не хочет быть плохим. Он решает отправиться в путешествие по аркадным играм разных жанров, чтобы доказать всем, что и он тоже может быть героем. На своем пути Ральф встречает героев разных игр — хладнокровную сержанта Калхун из игры Hero’s Duty, оберегающую планету от нашествия инопланетных захватчиков, и сладкую на вид, но острую на язычок Сластену фон Дю, чье существование в гоночном симуляторе Sugar Rush внезапно оказывается под угрозой. Наконец-то Ральфу выпадает шанс показать, что он умеет не только разрушать!",
 "f-wd174385": "Жизнь 19-летней Алисы Кингсли принимает неожиданный оборот. На викторианской вечеринке, устроенной в её честь, Алисе делает предложение Хэмиш - богатый, но глупый сын лорда и леди Эскот. Не дав ответа, девушка убегает и идёт за кроликом, замеченным ею на лужайке. Кролик как кролик, вот только он одет в камзол и всё время смотрит на карманные часы. Алиса гонится за Белым Кроликом через весь луг и видит, как он исчезает в кроличьей норе.",
 "f-wd200873": "События этого фильма разворачиваются через четыре года после того, что произошло в «Парке Юрского периода». На близлежащем острове динозавры выжили и адаптировались к дикой природе. Но вот находится Некто, кто хочет перевезти их на материк и заработать на этом, не понимая, какими могут быть последствия, и посылает на остров своих людей.\r Джон Хэммонд, который потерял контроль над своей компанией, считает, что у него появился шанс исправить свои прошлые ошибки. Он, в свою очередь, снаряжает экспедицию во главе с Яном Малкольмом, чтобы появиться там до высадки наемников.\r В результате происходящих событий две эти конфликтующие группы вынуждены объединиться перед лицом смертельной опасности. И, как потом выясняется, времени им отпущено совсем немного.",
 "f-wd212775": "В 1908 год, империя Цин. Трёхлетний Пуи становится императором Поднебесной. К императору-ребенку относятся как к божеству. Он может делать все, кроме одного - покидать пределы дворца. До Запретного города не долетает ветер перемен, сотрясающий мир за его стенами. Но жизнь последнего императора Китая оказывается частью великой истории XX века.",
 "f-wd610502": "Большой муравейник поделен на две части: там живут муравьи-рабочие и муравьи-солдаты. Рабочие трудятся с утра до ночи, а солдаты воюют с термитами под командованием властного и завистливого генерала Мэндибала. Так было всегда. И никому, кроме муравья Антца, работающего на строительстве туннеля, не приходит в голову, что все может быть по-другому. Однажды в бар на танцы тайно приходит принцесса Бала и там знакомится с Антцом. Он влюбляется в красавицу с первого взгляда. Чтобы еще хоть раз увидеть ее, Антц меняется местами с приятелем-солдатом Вивером и отправляется на военный парад не ведая, что ждет его впереди.",
 "f-wd498434": "Кто такой Винни Пух, знают все. Этот мультфильм производства компании Уолта Диснея основан на оригинальных иллюстрациях четырехтомного собрания о Винни Пухе Эрнеста Шепарда. Познакомьтесь с Винни Пухом, каким его видят англоязычные ценители и который, конечно, отличается от русской версии Бориса Заходера.",
 "f-wd191803": "Много времени утекло с тех пор, как лев Симба сверг своего злого дядю Шрама и вернул трон короля саванны. У него и королевы Налы уже подрастает дочь — принцесса Киара. Однако порученная легкомысленным заботам наших старых знакомых Тимона и Пумбы, проказливая и непослушная Киара пока никак не похожа на будущую королеву. Однажды сбежав в Запретную Землю, она встречает там львенка Кову, который становится ее лучшим другом. Да только принцесса не знает, что эта дружба может стоить ей короны! Кову — наследник Шрама, и пусть он не пошел в старого интригана, его мать Зира спит и видит, как бы усадить сына на трон. И чем прочнее дружба между Киарой и Кову, тем гуще тучи над племенем Симбы...",
 "f-wd30931": "На этот раз Джеймс Бонд в глубокой конспирации проводит операцию в Северной Корее. Однако его разоблачают, после чего Бонд оказывается за решеткой.Сумев выбраться из плена только через несколько месяцев 007 возвращается к своей привычной жизни, однако вскоре ему вновь приходится вступить в противоборство со своими корейскими «друзьями» — он узнает о плане британского миллиардера Густава Грейвса создать супероружие, и о его взаимодействии на этом поприще с корейскими военными…",
 "f-wd221168": "Людям Икс, во главе с профессором Чарльзом Ксавье, приходится вступить в битву с самой эволюцией в лице их воскресшего товарища по команде... Джин Грэй, возрожденная в облике Темного Феникса, представляет опасность не только для самой себя, но и для мутантов и для всей человеческой расы. А когда наконец найдено возможное лекарство – то, что может предотвратить генетические мутации – наступает время решающей битвы между Людьми Икс, Братством Магнето и человечеством.",
 "f-wd188850": "Молодая девушка Софи собирается выйти замуж и мечтает о том, чтобы церемония прошла по всем правилам. Она хочет пригласить на свадьбу своего отца, чтобы он отвел ее к алтарю. Но она не знает, кто он, так как ее мать Донна никогда не рассказывала о нем. Софи находит дневник матери, в котором та описывает отношения с тремя мужчинами. Софи решает отправить приглашения всем троим! Все самое интересное начинает происходить, когда на свадьбу приезжают гости…",
 "f-wd309086": "Не успев как следует насладиться прелестями семейной жизни, молодожен Феликс, агент ЦРУ и старый друг Джеймса Бонда, на собственной шкуре познает все коварство и жестокость колумбийской наркомафии. Его красавицу жену умышленно лишают жизни, а его самого бросают на съедение акулам. Агента 007 безусловно не устраивает такое отношение к его друзьям и он, нарушив все инструкции и приказы, но не забыв прихватить с собой множество хитроумных примочек из шпионского арсенала, отправляется на поиски кровожадного наркобарона.",
 "f-wd275167": "Барри Би Нельсон - пчёл, только что закончивший колледж и весьма разочарованный дальнейшей карьерой. Ведь единственный выбор, открывающийся перед ним - сбор мёда. Отправившись куда глаза глядят, Барри попадает в передрягу, из которой его вызволяет Ванесса, нью-йоркская цветочница. Барри немедленно влюбляется в спасительницу, и перебирается жить поближе к ней. Именно в Нью-Йорке он узнает, что мёд, который с таким трудом добывают пчёлы, люди съедают. И Барри решает предъявить человечеству иск.",
 "f-wd676513": "В жизни газетного магната Уильяма Пэрриша появляется сама Смерть, принявшая обличье молодого человека по имени Джо Блэк. Смерть, уставшая от своих привычных обязанностей, предлагает Пэрришу необычное соглашение: магнат станет проводником Джо в мире живых, а по окончании каникул Смерть заберет Пэрриша с собой.",
 "f-wd24278982": "Неувядающий авантюрист и пытливый археолог-исследователь по-прежнему в седле. На этот раз ему придётся столкнуться с непростой задачей, которую решить на раз-два вряд ли получится. Но разве тот самый Индиана Джонс даст слабину и отступит при виде даже самой безнадёжной ситуации? Это вряд ли! Поэтому безумные приключения и нескончаемые интриги вновь возрождаются в искрометном продолжении всемирно известной саги о «простом герое» Индиане Джонсе.",
 "f-wd269810": "Биографический фильм о жизни премьер-министра Великобритании Маргарет Тэтчер. С момента когда она заинтересовалась политикой и до сегодняшнего дня.",
 "f-wd465478": "Кризис среднего возраста, случившийся у адмирала Кирка, казался ему вещью первостепенной важности. Но только до тех пор, пока он не получил сообщение с планеты Сеты Альфа 5 о том, что объявился его давний враг, жаждущий мщения.  Хан, генетически созданный сверхчеловек, с сильно развитыми интеллектом, физической силой и амбициями, уже встречался один раз команде «Энтерпрайза », но тогда его и его людей, решивших захватить корабль, остановили и в наказание оставили на первой попавшейся пригодной для жизни планете.  И вот теперь, спустя 15 лет, Хан смог выбраться из своего принудительного отшельничества. И цель у него только одна — уничтожить Кирка, которого он считает виновником всех своих несчастий. Давнее противостояние двух сильных личностей теперь развернется на фоне секретных экспериментов Федерации по терроформированию планет.  Но на этот раз Кирку придется победить, чего бы это ни стоило, и начинать ему придется с победы над собственным эго…",
 "f-wd713979": "Богатый престарелый южанин узнает, что скоро должен умереть. Все члены его жадной семьи, за исключением шалопая-сына, лезут из кожи вон, лишь бы получить наследство.",
 "f-wd269887": "Депрессивный главный герой всегда и всем говорил «нет» - например, друзьям, если они зовут куда-то. Но в один прекрасный день он заключает соглашение, по которому всегда должен отвечать «Да» на любое предложение...",
 "f-wd327604": "5 друзей отправляются в уединённый домик в лесу, среди них Эш Уильямс - обычный молодой человек, приехавший туда вместе со своей девушкой Линдой и друзьями, чтобы провести несколько спокойных дней вдали от города. В подвале они находят загадочную книгу с древними заклинаниями и магнитофонную запись, после чего по незнанию пробуждают древнее зло. Друзья становятся жертвами сверхъестественной силы, превращающей их против друг друга. Оказавшись отрезанным от внешнего мира, Эш вынужден бороться за жизнь и искать способ остановить демоническое присутствие, пока оно не поглотило всех обитателей дома.",
 "f-wd220376": "Есть герои, есть супергерои, и есть Хэнкок. Обладание сверхспособностями предполагает ответственность, все знают это — кроме него. За любую задачу он берётся с душой и лучшими намерениями, спасает жизни людей — ценой нечеловеческих разрушений и неисчислимого ущерба. В конце концов, терпение общественности подходит к концу: люди благодарны своему местному герою, но иногда не понимают, чем заслужили такое наказание.Хэнкок не из тех парней, кого волнует какое-то там общественное мнение, но однажды, после очередного подвига, спасая высокопоставленного пиарщика Рэя, он вдруг понимает, что в некотором смысле он может быть уязвим. С этим трудно смириться, особенно по мнению Мэри, жены Рэя, считающей, что Хэнкок попросту безнадежен.",
 "f-wd235347": "Ветеран Гражданской войны в США Джон Картер против своей воли оказывается на Марсе, где попадает в плен к воинственным четырехметровым туземцам. Картеру предстоит не только спастись самому, но и спасти принцессу Дею Торис из Гелиума.  По мотивам первой книги Эдгара Берроуз \"Принцесса Марса\" из трилогии «Хроники Марса» .",
 "f-wd675468": "История о Чарли, ученике старшей школы в Питтсбурге, стеснительном и непопулярном. На наших глазах Чарли взрослеет, меняется круг его общения, меняется его мнение о мире.",
 "f-wd623724": "Обладатель замечательной фамилии, санитар Грэг Трахер, отправляется за город, чтобы познакомиться с родителями своей девушки Пэм. Здесь Грэг собирается торжественно просить руки возлюбленной. Но, к несчастью, Грэг — парень невезучий, и любые благие начинания в его исполнении превращаются в сущий кошмар. Несчастный Трахер и в самом страшном сне не предполагал, какие его ждут испытания. Дело в том, что отец Пэм, Джек Бернс, — отставной сотрудник ЦРУ, устраивает приятелям дочери свою особую и жесткую проверку. Эта проверка включает в себя даже специальный тест на детекторе лжи!",
 "f-wd4499813": "Группа пришельцев, скрываясь от своих врагов, пытается найти прибежище на Земле.",
 "f-wd726294": "История о том, как простой американский мальчишка Уильям Миллер волею случая стал корреспондентом авторитетного музыкального журнала «Роллинг Стоун» и отправился по заданию редакции в турне с группой «Стиллуотер».  В компании суровых рокеров, юных фанаток и бурлящих в крови гормонов парень делает свой первый шаг в полную удивительных приключений взрослую жизнь расклешенных семидесятых. И уж, поверьте, эти самые приключения не заставят себя ждать!",
 "f-wd535081": "Картина рассказывает о последнем периоде жизни писателя Льва Толстого. Прожив долгую жизнь, устав от отчужденности и вражды в отношениях с женой Софьей Андреевной, в ночь на 28 октября 1910 года, в пятом часу утра с 39 рублями в кармане Лев Толстой тайно уехал из дому. Простудившись по дороге, он заболел воспалением легких и нашел последний приют на станции Астапово.",
 "f-wd25397044": "Фильм о нескольких днях из жизни писателя Сергея Довлатова в Ленинграде начала 70-х годов накануне эмиграции его друга, будущего лауреата Нобелевской премии Иосифа Бродского. Это круговорот из парадоксальных и смешных ситуаций. Столкновение с криминалом, светская и литературная жизнь Ленинграда, киностудия «Ленфильм», музыка, чтение стихов, ремесло журналиста, страстное желание купить для своей дочери куклу, которую не достать нигде.В череде жизненных коллизий, иногда смешных, а иногда пронзительных, зритель открывает для себя жизнь тонкого, блестящего, ироничного человека, который выбирает свой творческий путь, чтобы позже превратиться в одного из самых популярных русских прозаиков XX века.",
 "f-wd74568": "Фильм-сказка по мотивам онежских былин. Удалой новгородский гусляр и купец Садко побеждает в споре новгородских бояр, с верной дружиной путешествует по всему свету в поисках Птицы-Счастье, оказывается в гостях у морского царя, и возвращается в Новгород, познав, что истинное счастье - в земле родной, и ждущей его там любимой. В фильме звучит музыка из одноимённой оперы Римского-Корсакова.",
 "f-wd529053": "Ночью в подъезде своего дома убита молодая женщина. На теле не обнаружено никаких следов насилия... Зыбкое равновесие между Светлыми и Тёмными нарушено. И чаша весов склоняется в сторону Тёмных. Но убитая — Тёмная иная, а значит подозрение падает на Светлых. Гессер срочно собирает команду: обвинение в убийстве — серьёзная проблема. Он обязан реагировать. И, прежде всего, понять кто где был и чем занимался в указанное Тёмными время. Выясняется, что алиби отсутствует только у Городецкого...",
 "f-wd85859809": "1962 год, в советском Новочеркасске – забастовка на главном городском заводе, люди требуют снижения цен на продукты и повышения зарплат. Когда к забастовке присоединяются рабочие других предприятий, правительственная комиссия решает ввести в город армию, и через считанные часы на улицах звучат выстрелы боевыми патронами. Работница парткома Людмила искренне верит в то, что строит коммунистическое общество и возмущается поведением заводских смутьянов. Но когда в бойне на площади без вести пропадает её дочь-подросток, стройная картина мира убежденной коммунистки рушится в одночасье.",
 "f-wd1967124": "Первый советский художественный звуковой фильм, получивший приз I Венецианского МКФ. Действие происходит в 1923 году. В СССР идёт борьба с голодом и разрухой. Фильм повествует о беспризорных подростках, для которых создаётся трудовая коммуна, где их должны собрать и перевоспитать...",
 "f-wd1786295": "В августе 1945-го в далекий поселок с названием Край с войны возвращается бывший танкист Игнат, чья страсть — паровозы. Он узнает, что на уединенном острове с довоенных времен брошен немецкий паровоз, и принимается его восстанавливать. Но, оказывается, у паровоза уже есть имя — «Густав», и есть хозяйка — Эльза, дочь немецкого инженера, арестованного в начале войны. Да и для сельчан одержимый мечтой, свободный Игнат — чужак. Страсти закипают шекспировские, причем в них задействованы не только люди, но и несколько паровозов, почти живые существа, у каждого свое имя…",
 "f-wd2529345": "В прологе говорится о далеком прошлом и памятниках архитектуры Юкатана.  Идиллическая новелла «Сандунга» — воспоминание о Мексике дофеодальных времен.  Новелла «Магей» — драматическая история любви бедного пеона и его невесты.  «Фиеста» — романтическая любовная история и бой быков.  «Солдадера» (четвертая новелла) не была снята Эйзенштейном. По замыслу она посвящалась мексиканской революции 1910 года. В последней новелле использованы фрески Ороско, Сикейроса, Риверы.",
 "f-wd4185026": "Лирическая комедия с элементами сатиры, рисующая быт и нравы провинциального городка первой половины двадцатых годов, рассказывает о забавных приключениях домработницы и закройщика, выигравших крупную сумму по облигации госзайма.",
 "f-wd15059365": "К уволенному капитану подводной лодки обращается таинственный наниматель с предложением возглавить экспедицию по поиску затонувшей у берегов Чёрного моря субмарины, предположительно загруженной золотом. Желая подзаработать на этом деле и отомстить бывшему работодателю, капитан собирает команду из русских и английских моряков и отправляется в плавание, но вскоре понимает, в какое рискованное предприятие ввязался.",
 "f-wd359119": "1853 год. Крымская война. Русская парусная эскадра под командованием адмирала Нахимова наголову разбила превосходящий её по качеству и численности турецкий флот, руководимый английскими советниками. Это было историческое Синопское сражение. Адмирал погиб, находясь на передовой линии Севастопольской обороны в 1855 году.",
 "f-wd1210857": "Мальчик Петя был очень пугливым. А девочка Тома была «царевной-несмеяной», так как никогда не улыбалась и часто плакала. Вот их родители и решила обратиться к доктору.  Доктор был необычный, у него были чудесные леденцы от страха, конфеты от злости и коварства, глупости, грусти, вранья, болтовни…  Да вот беда: чемоданчик с чудо-медикаментами попадает в чужие руки. Последствия могут быть самыми плачевными.  Тома и Петя вместе с бабушкой и доктором отправляются на поиски чемоданчика…  Экранизация одноимённой повести Софьи Прокофьевой.",
 "f-wd1444948": "Париж, 1995 год. Во время подготовки выставки Пиросмани Антон Гоголадзе встречает старую даму с лукавым взглядом по имени Марсель Ишак. У нее есть старинная рукопись, написанная в начале века матерью Антона, грузинской княжной Сесилией Абашидзе, где рассказывается история бурной и плутовской жизни повара-путешественника Паскаля Ишака, история его безумной последней любви, которая настигла его в Грузии... В двадцатые годы судьба забрасывает его в далекую Грузию. Паскаль намеревается пробыть там всего несколько дней. Он не знает, что окажется вовлечен в водоворот интересных и важных событий, что его ждут слава, удача и безумная любовь. И уж конечно ему неведомо, что через много десятилетий в Париже обнаружится рукопись, которая хранит память обо всех удивительных происшествиях...",
 "f-wd1969148": "Конец XIX века. Две благополучные семьи, Загадочный Иоган, владелец фотостудии в подвальном помещении, где создан некий фотографический театр Маркиз де Сада. И фотографические открытки с униженной наготой женского тела, вызывающие похоть и злорадствующее торжество власти.  Взгляд фотографа умеющий видеть в девочке ангельские кудри и милую улыбку, и тот же взгляд, разлагающий тело, взгляд порнографа. Иоган отмеченный дьяволом, Иоган убивающий душу. Именно он постепенно разрушает благополучие семей и превращает обычных людей в уродов. И аромат порока охватывает мир…",
 "f-wd1138065": "Советский документальный кинофильм, созданный к десятой годовщине со дня смерти Владимира Ильича Ленина. Картина состоит из трёх частей, каждая из которых построена как песня и посвящена определённой теме.",
 "f-wd4055402": "Остросюжетная версия традиционного конфликта поколений. Дочь - трудный подросток, «металлистка», отец - милиционер, «мент». У каждого из героев свои ценности, свой отдельный мир... Но когда приходит настоящая беда, они понимают, как много значат друг для друга. Спасая дочь, верный страж закона сам вершит правосудие...",
 "f-wd4057877": "Историко-биографический фильм о создании в 1779 году русского Черноморского флота под руководством великого флотоводца Федора Федоровича Ушакова.",
 "f-wd4508597": "1917 год. Солдат Иван Шадрин отправляется с фронта в революционный Петроград, с письмом к Ленину. Шадрин и его товарищи верят, что Ленин даст ответы на все вопросы, волнующие рабочих. В то время на Петроград наступает войско генерала Краснова...",
 "f-wd85864528": "В сумрачном и холодном Екатеринбурге живет автослесарь Петров, его жена Нурлыниса и их маленький сын. Однажды все они заболевают гриппом, и эта обычная для жителей севера напасть преображает их жизнь и раскрывает в ней неведомые доселе нюансы, порой пугающие, а порой и забавные. Еще больше усугубляет временное безумие семьи тот факт, что разыгрывается оно в канун Нового года. Сначала сам Петров, чувствуя, что заболевает, отправляется домой. По дороге, в автобусе, в накатывающем температурном бреду, каждое услышанное слово, каждая случайно брошенная фраза превращается в воспаленном сознании героя в полноценную картину. Дежурное «всех, кто сейчас у власти, к стенке надо ставить» оборачивается галлюцинацией-боевиком с революционным уклоном. Монолог безумного старика — в жестокую социальную драму. Совсем неожиданный поворот дело приобретает, когда внезапно на дороге появляется старый друг Петрова, жаждущий как следует отпраздновать грядущий праздник...",
 "f-wd331960": "Для строительства ГЭС островная деревня Матера должна быть затоплена. Немногочисленные ее обитатели готовятся к переселению и, каждый по-своему, прощаются с родными местами.",
 "f-wd1213173": "Осип Иванович Дымов, титулярный советник и врач тридцати одного года, служит в двух больницах одновременно: ординатором и прозектором. С девяти часов утра и до полудня принимает больных, потом едет вскрывать трупы. Но его доходов едва хватает на покрытие расходов жены, помешанной на талантах и знаменитостях в художественной и артистической среде, которых она ежедневно принимает в доме.",
 "f-wd3540877": "В общем-то он обыкновенный парень - шофёр Пашка Колокольников. Живёт себе, работает, мечтает, встречается и расстаётся с самыми разными людьми. Но есть у него особая черта: он чувствует себя счастливым, только если вокруг всем хорошо.  Собственная жизнь волнует его меньше, чем судьбы других людей. Ради них он и дурачком прикинется, и подвиг совершит...",
 "f-wd4315360": "В школе его прозвали Мухой. А он и был похож на муху. Невзрачный, взъерошенный и настырный. Муха позволял себе быть самим собой, стоять на голове в подъезде, раскачиваться на кованных воротах и отчаянно любить тоненькую девочку с черными косичками. И остервенело выколачивать из барабанов ритмы вышедшего из моды джаза.",
 "f-wd4417231": "В подмосковном дачном поселке расквартирован полк танкистов. Сюжет строится вокруг двух сестер, абсолютно разных, но одинаково влюбленных. Одна — серьезный математик, другая — легкомысленная стрекоза. В центре внимания девушек бравый военный. Жизенные перипетии, смешные и сложные ситуации, интриги, слезы, радость, но все строится вокруг одного — любви.",
 "f-wd2250632": "Действие фильма происходит в неназванной стране, где царит диктатура. Бывший летчик, а теперь водитель такси Антонио хочет остаться в стороне от борьбы. Но, жизнь заставляет его сделать выбор, который осложняет возлюбленная героя Мария.",
 "f-wd117425181": "Альмут мечтала быть шеф-поваром, а романтичный Тобиас не мог оправиться после развода. Случайная встреча изменила их жизнь — и вот у них уже очаровательная дочь, уютный дом и процветающие карьеры. Идиллию нарушает роковая новость: Альмут предстоит борьба с серьезной болезнью. Не теряя надежды, пара осознаёт ценность каждого отведённого момента и решает жить так, чтобы ни одна минута не пропала зря.",
 "f-wd124841936": "Братья-близнецы Хэл и Билл находят на чердаке заводную обезьянку, принадлежавшую их отцу. С каждой вспышкой ее механических глаз следуют смерти - жестокие, необъяснимые, похожие на цепь зловещих совпадений. Годы спустя кошмар возвращается, и мрачная игра продолжается. Тьма сгущается, страх усиливается, а реальность становится призрачной, превращая происходящее в пугающий лабиринт. Никто не знает, когда обезьянка хлопнет в ладоши в последний раз и кто исчезнет следом. Незримая сила ведет эту игру, а правила остаются тайной. Основан на одноименном рассказе Стивена Кинга.",
 "f-wd29226331": "Питер Квилл никак не может смириться с потерей Гаморы и теперь вместе со Стражами Галактики вынужден отправиться на очередную миссию по защите Вселенной.",
 "f-wd386245": "Океан без конца и без края. Необитаемый островок. Жара, пальмы, бананы, кабаны, родник чистой пресной воды — и таинственная пещера… Именно на этот островок попадает отряд мальчишек, оставшихся в живых после авиакатастрофы. Неожиданный поворот судьбы подталкивает многих из них забыть обо всем: сначала — о дисциплине и порядке, затем — о дружбе и порядочности, а в конце концов — и о самой природе человеческой.",
 "f-wd1347609": "Капрала Джо Бауэрса Пентагон выбирает для участия в сверхсекретной программе по гибернации людей. Проведя в спячке пятьсот лет, он пробуждается и попадает в цивилизацию, где интеллектуальный уровень людей намного ниже того, которым обладает он. В итоге, Джо оказывается самым умным человеком на планете...",
 "f-wd1170168": "Ученый Чикагского Национального Исторического музея возвращается из экспедиции в Южную Америку с большим грузом археологических экспонатов. Но, когда ящики попадают в хранилище музея, выясняется, что сам ученый пропал, а на борту транспортного судна, доставлявшего груз, произошла серия загадочных убийств.\r После того, как в музее начинают пропадать люди, полиция Чикаго начинает расследование. Офицер Винсент Д’Агоста с помощью Марго Грин, доктора исторических наук, пытается выявить связь между исчезновениями людей в музее и убийствами на борту корабля.\r То, что они обнаружили, не могло им присниться и в самых страшных кошмарах…",
 "f-wd21433535": "Каждый день поезд проносит Рэйчел мимо очаровательного коттеджа, где живет идеальная на первый взгляд пара. Но однажды идиллия разрушится — прекрасная незнакомка бесследно исчезнет. Рэйчел окажется втянута в весьма запутанную историю, ведь только она видела из окна то, что было скрыто от всех.",
 "f-wd19867575": "От лайка в соцсети до спасения мира — один шаг. Сегодня ты френдишь бывшего одноклассника, а завтра — он тащит тебя под пули. Кто ж знал, что заядлый любитель пончиков превратится в похожего на скалу супершпиона.",
 "f-wd19347583": "Действие происходит в 1920-х годах в Копенгагене. Иллюстратор и художник Герда Вегенер просит своего мужа Эйнара Вегенера попозировать в качестве женской модели. Портреты приобретают популярность и Герда продолжает писать картины со своим мужем в качестве женщины. Эйнару нравится собственная женская внешность и он начинает жить под именем Лили Эльбе. Впоследствии Эльбе становится первым человеком, прошедшим хирургическую коррекцию пола.",
 "f-wd467953": "В маленьком городке, окруженном кукурузными полями, появляется 12-летний проповедник Исаак. Он призывает детей убивать взрослых, чтобы их кровью напитать жаждущие поля. Исаак запрещает детям играть, убеждая принести себя в жертву полям в день 19-летия. Многие пытаются бежать, но он настигает их!",
 "f-wd28170369": "Берт Граммер и его сын Трэвис Уэлкер отправляются в Канаду, чтобы расследовать серию атак гигантских червей, и оказываются среди грабоидов. Берт начинает подозревать, что военные пытаются приспособить подземных монстров для своих нужд, но тут дело принимает неожиданный оборот: один из грабоидов отравляет его. Единственное спасение — сделать антидот из свежего яда, но для этого надо подоить грабоида.",
 "f-wd16972012": "Команда отчаяных гонщиков отправляется в Канаду, чтобы участвовать в Ралли 1000. На своему пути они подрезают грузовик, следующий по трассе 17 - заброшенной дороге, которую людская молва окрестила Аллеей Убийств. И вот уже цель поездки отходит на второй план, и начинается гонка за жизнь.",
 "f-wd324557": "Элис продолжает охоту на корпорацию «Амбрелла», которая разрабатывает новые способы управления заражёнными и создания биологического оружия. В поисках выживших она отправляется в Лос-Анджелес, но обнаруживает город, заполненный ордами зомби и оказавшийся в ловушке огромной тюрьмы. Вместе с группой людей Элис пытается выбраться из смертельного окружения и найти безопасное место, о котором ходят загадочные слухи. Однако за стенами тюрьмы их ждёт новая угроза, а противостояние с «Амбреллой» становится всё опаснее.",
 "f-wd1353813": "Во время учений солдаты Национальной гвардии США делают привал на пограничной заставе в Нью-Мексико и, к своему удивлению, обнаруживают, что там никого нет. Получив сигнал тревоги, исходящий с отдаленной горной возвышенности, группа военных решает отправиться в этот район, чтобы помочь терпящим бедствие. Спасатели не знают, что это местечко когда-то посетила печально известная семья Картеров и что их поджидают кровожадные мутанты-каннибалы…",
 "f-wd470692": "Ричард — американский юноша, жаждущий приключений — отправляется в Тайланд, где в дешевой гостинице знакомится со странным человеком. Этот человек передает ему карту таинственного острова, где «трава» растет как сорняк, а на пляже живет коммуна. Это и есть рай на Земле. Ричард знакомится с парочкой французов, и они втроем отправляются на этот остров.",
 "f-wd219150": "Джону Константину удалось не только побывать в аду, но и вернуться обратно. Родившись с неугодным самому себе талантом — способностью распознавать помесь ангелов и демонов, которые бродят по земле в облике людей, — Константин под давлением обстоятельств пытается совершить самоубийство, лишь бы избавиться от мучительных видений. Но неудачно. Воскрешенный против собственной воли он снова оказывается в мире живых. Теперь, отмеченный печатью суицида и получивший временное право на жизнь, он патрулирует границу, разделяющую рай и ад, тщетно надеясь на обретение спасения путем сражения с земными ставленниками зла.",
 "f-wd48988117": "1969 год. Группа разношерстных личностей останавливается на ночь в когда-то популярном отеле «Эль Рояль», расположенном на границе штатов Невада и Калифорния.  В здании отеля собрались неприветливый священник, певица Дарлин, энергичный продавец пылесосов и подозрительная девушка с Юга. Вместе с ними ночь в отеле проводит молодой консьерж. Каждому из них есть что скрывать, и у каждого из них будет шанс искупить прошлые грехи. Но ситуация только осложняется, когда в «Эль Рояль» появляется зловещий, но обаятельный лидер культа, желающий получить свое.",
 "f-wd19938437": "Армию генетически модифицированных обезьян ожидает новый вызов: они вынуждены вступить в смертельную схватку с армией людей под руководством безжалостного полковника. После невообразимых потерь среди своих воинов вождь обезьян Цезарь начинает личную борьбу с темными инстинктами и собирается отомстить за весь свой вид. В конце концов он и полковник должны будут сойтись в эпической битве, которая решит, кто теперь будет править на Земле — люди или обезьяны.",
 "f-wd23016644": "Молодой парень по прозвищу Малыш обожает стильную музыку, быструю езду и адреналин в крови. Вся его жизнь — это сплошные погони и перестрелки, ведь он работает водителем, который помогает бандитам скрыться с места преступления. Однажды он по-настоящему влюбляется и решает выйти из игры, но сначала ему предстоит выполнить еще одно задание, которое вполне может оказаться последним в его жизни.",
 "f-wd41854": "Действие разворачивается на задворках Восточной Европы, где главный герой Джонни Блэйз безуспешно пытается справиться со своим проклятием. Его принимает на работу некая секта, которая пытается заполучить дьявола в тот момент, когда он пытается вселиться в тело его смертного сына на дне рождения мальчика.",
 "f-wd15631013": "Экспедиция под руководством Роба Холла отправляется на Эверест, сопровождая клиентов, которые хотят подняться на высочайшую вершину мира. Для одних это мечта всей жизни, для других - серьёзное испытание, требующее полной отдачи и доверия к гиду. Подъём проходит через череду лагерей, где каждый шаг даётся всё труднее, а условия становятся всё жёстче. По мере приближения к вершине нарастает напряжение: погода меняется, силы участников на исходе, а решения приходится принимать быстро и без права на ошибку. В этих условиях становится ясно, что главная задача - не только подняться наверх, но и найти путь обратно.",
 "f-wd499633": "Профессор Александр Хартдеген изобрел машину времени. Изобрел не потому, что он гений-ученый, а для того что бы отправиться в прошлое и спасти свою невесту от случайной пули. Но ее смерть предотвратить не удалось — прошлое нельзя изменить. В поисках ответа на вопрос «почему?» Хартдеген забирается на двести лет в будущее, застав Землю в ужасающем состоянии. Получив ранение и впав в беспамятство он и не заметил, как его машина прошла сквозь восемьсот тысяч лет истории планеты Земля. Человечество изменилось, века технократии канули в Лету, люди стали похожими на добрых папуасов, живущих в домах-люльках, подвешенных к скалам. Но у столь пасторальной картины есть и темная сторона. Часть человечества эволюционировало в морлоков — чудищ, живущих под землей в пещерах, и пожирающих тех, кто живет на земле.",
 "f-wd3010512": "На Белый Дом нападают террористы и берут в заложники президента США. И теперь бывший охранник главы государства - единственный, кто сможет его спасти…",
 "f-wd107473453": "Семейство легендарных исследователей путешествует по неизведанным и опасным землям, населенным фантастическими существами. Непрекращающиеся споры между членами семьи грозят сорвать их последнюю — и, безусловно, самую важную миссию.",
 "f-wd1140578": "Агенту ФБР Честеру Деcмонду поручают расследование загадочного убийства девушки по имени Тереза Бэнкс в городке Такома в окрестностях Твин Пикс. Вместе с напарником Честер выезжает на место преступления, но местный шериф не горит желанием идти на контакт. Взяв дело в свои руки, агенты во время осмотра тела убитой обнаруживают клочок бумаги с буквой Т под ногтем, а также след от кольца на пальце. Тем временем в офисе ФБР в Филадельфии агент Дейл Купер рассказывает о своём странном сне и просит назначить его на расследование убийства Терезы.",
 "f-wd23796643": "Прошло несколько лет с того момента, как в последний раз все было прекрасно. На мир надвигается новая угроза из космоса. Теперь Эммет обязан спасти Люси и других героев от печальной участи.",
 "f-wd4427670": "Июль 1942 года. Лейтенант Керженцев, его связной Валега и полковой разведчик Седых вместе с отступающими частями нашей армии идут мимо украинских деревень к Сталинграду, где уже формируются новые части… Фильм снят по повести Виктора Некрасова «В окопах Сталинграда»",
 "f-wd47005334": "Жуткие убийства в селе Диканька продолжаются. Жертвами загадочного Всадника стали уже одиннадцать девушек. Гоголя всё чаще начинают преследовать обмороки, сопровождающиеся видениями, но он верит, что это - сила, приближающая его к поимке душегуба. Однако, когда Гоголь узнаёт, что следующей жертвой Всадника должна стать Лиза, его возлюбленная, он теряется: хватит ли его способностей на то, чтобы противостоять убийце? К счастью, на помощь герою приходит охотник на ведьм, мастер восточных единоборств и философ Хома Брут. Вдвоём они проведут три страшных ночи в стенах старинной часовни, отпевая ведьму Ульяну и призывая самое жуткое порождение нечистой силы - Вия.",
 "f-wd4301835": "К старому профессору Сретенскому с его устоявшейся жизнью и порой нелепыми, но дорогими сердцу привычками, приезжают его непутевая дочь и юная внучка. О любви и нетерпимости этих людей друг к другу, порождающих конфликты, об умении понимать и прощать…",
 "f-wd4164467": "Саша был смыслом ее жизни. Теперь, когда сын подрос, у нее появилось больше свободного времени и она позволила чуткому Николаю Сергеевичу ухаживать за собой. После летней поездки сына к отцу она стала замечать в Саше перемены. Тайком прочитав письмо его отца, она узнала, что сын хочет уехать.",
 "f-wd4451600": "Биографический фильм о жизни и творчестве выдающегося украинского поэта и художника Тараса Григорьевича Шевченко. Сын крепостного крестьянина, он блестяще окончил Академию художеств и еще в юности завоевал славу вольнолюбивыми стихами. Но его ждали тяжелые испытания…",
 "f-wd28912985": "Игорь Гром — опытный следователь из Санкт-Петербурга, известный своим пробивным характером и непримиримой позицией по отношению к преступникам всех мастей. Неимоверная сила, аналитический склад ума и неподкупность — всё это делает майора Грома идеальным полицейским. Работая не покладая рук, он всегда доводит начатое до конца и никогда не пасует перед трудностями, стоящими на пути.",
 "f-wd107662895": "Ленинград, 1938 год. Сотрудник органов капитан Фёдор Волконогов, прежде находившийся на хорошем счету у начальства, вынужден пуститься в бега и скрываться от бывших сослуживцев. Ночью ему является расстрелянный накануне коллега и сообщает, что в аду его уже заждались муки вечные, но этого можно избежать, если перед смертью покаяться, и хотя бы один человек его простит. Капитан Волконогов отправляется по родственникам репрессированных в поисках прощения.",
 "f-wd60831493": "Сорокалетний Влад живёт и работает сторожем в старом санатории под снос. Эта работа очевидно нужна ему для того, чтобы жить затворником. Однажды ночью в санатории появляется супружеская пара — Вера и Стас. Они в бегах — их преследуют бывшие друзья и партнёры Стаса. Влад решает помочь супругам, потому что сам скрывается от прошлого. Каждому из героев грозит неминуемая расплата за выбранный однажды неверный жизненный путь, но, помогая друг другу, они попытаются искупить вину за прошлое.",
 "f-wd111629600": "Когда не знающие жалости войска Праматери угрожают тихой деревне на отдалённой луне, их единственной надеждой на выживание становится загадочная незнакомка.",
 "f-wd221102": "Действие фильма происходит спустя шесть месяцев после того, как вирус ярости опустошил Лондон. Армия США восстановила порядок и заселяет город, который находился под карантином...",
 "f-wd55815471": "Случайная встреча перевернула их привычный мир. Она — прилежная студентка и образцовая дочь, а он — дьявольски притягательный бунтарь из богатой семьи. Живя в параллельных вселенных, они бы вряд ли даже взглянули друг на друга. Однако этому знакомству суждено разделить жизнь влюбленных на до и после…",
 "f-wd4402914": "На телевидении запускается новое реалити-шоу под названием «Пионерлагерь». По итогам кастинга, пятеро юношей и пятеро девушек, во главе с молодой телеведущей Алисой Тен, отправляются в заброшенный пионерский лагерь советских времен.  По правилам, каждую неделю кто-то из участников должен покинуть шоу и вернуться домой. Последний, кто останется на проекте, получит главный приз: один миллион рублей. Но внезапно правила игры меняются: невидимый наблюдатель объявляет, что теперь наградой для победителя будут не деньги, а его собственная жизнь.  Одержимый маньяк, скрывающий свое лицо за маской лошади, выходит на кровавую охоту за участниками реалити-шоу. Детские страшилки, которые он когда-то слушал в пионерлагере, оживают и становятся сюжетом его собственных убийств…",
 "f-wd14565630": "Воин, пытающийся забыть жестокость своего прошлого, вынужден вновь взять в руки меч, чтобы сразиться с невообразимой силы божеством.",
 "f-wd134650614": "Актриса театра и кино Галина Коврова была настоящей суперзвездой. Ее любили все: от мала до велика, от крестьян до высоких партийных чиновников. Среди поклонников ее таланта был и товарищ Сталин. Фильмы и спектакли с ее участием собирали полные залы. А потом наступили 40-е, пришла война, и мир вокруг навсегда изменился.",
 "f-wd4463348": "По одноименной повести Джерома К. Джерома. Однажды трое приятелей-холостяков, лондонских жителей, решили сделаться ближе к природе и отправиться в лодочное путешествие по Темзе, прихватив с собой собачку Монморенси...",
 "f-wd67200663": "Рокки удалось захватить на золотых приисках власть и навести там порядок, но имеются недовольные. Правительство и жаждущие мести криминальные элементы развязывают с ним кровавую войну.",
 "f-wd113668560": "Действие происходит в 1960-х годах на Среднем Западе, где появляется вымышленный клуб мотоциклистов. На протяжении десятилетия клуб превращается из места, где собирались местные аутсайдеры, в зловещую банду, угрожающую уникальному образу жизни первоначальной группы.",
 "f-wd21780574": "Сарасвати — простая девушка, работающая в библиотеке. О таких, как она, говорят лишь одно: книжный червь, невзрачная простушка, которой далеко до идеала красоты. Именно эта простота мешает Сарасвати выйти замуж и наконец уехать из отчего дома. Родители цепляются за любую возможность о предложениях на замужество, но отказы со стороны потенциальных женихов следуют один за другим. Младшая сестра Кавери тихонько ненавидит Сарасвати за то, что по её вине она не может первой выйти замуж за своего возлюбленного и переехать в США. Устав от упрёков со стороны своих родителей, сестры и коллег, Сарасвати наконец, решает взять свою судьбу в свои руки. Она просит помощи у своего соседа Индера, который с момента своего заселения в дом, старался всячески избегать её. После долгих уговоров девушки, Индер всё-таки соглашается помочь Сарасвати с преображением и найти своё женское счастье в лице её коллеги Абхиманью, в которого она тайно и давно влюблена…",
 "f-wd65081848": "Осужденный преступник вынужден помогать полиции, чтобы впервые в жизни увидеть свою дочь...",
 "f-wd130367880": "Молодожены переезжают в новый дом в спокойном районе. Сильный шторм и непонятные силы вносят разлад в их отношения. Васанту нужно выяснить, что происходит на самом деле, пока их брак не окончательно не развалился.",
 "f-wd112030632": "Виджай, блудный сын бизнес-магната Раджендрана соглашается взять бразды правления в свои руки, к большому огорчению своих братьев. Но сможет ли Виджай проявить себя как достойный наследник, а также воссоединить свою уже распавшуюся семью?",
 "f-wd1228474": "Вечный сюжет о Золушке: восхождение из ничего к вершинам славы. Джимми — бедный ребенок, выступает с дядей на улицах, зарабатывая на кусок хлеба. Однако, мирное существование семьи нарушает инцидент в доме одного богача. После этого Джимми и его мать вынуждены покинуть родной город. Проходят годы. Джимми своим трудом и талантом добивается славы. Встречает он и свою любовь. И надо же случиться, чтобы его девушка оказалась дочерью богача, оскорбившего Джимми и его мать много лет назад…",
 "f-wd44280": "Это история о Самар Ананде, майоре индийской армии из отряда сапёров. Все поражаются, как без капли страха за свою жизнь он обезвреживает бомбы, он совсем не боится смерти. Однажды он спасает тонущую Акиру, репортёра Discovery Channel, и нечаянно забывает у неё свою куртку. Акира находит в ней его дневник и узнаёт историю о Самаре, его единственной любви Мире и одной клятве, которая перевернула всю его жизнь. ..",
 "f-wd1659542": "Популярный эстрадный исполнитель пользуется огромной популярностью у девушек. Поклонницы влюблены в него, но отвечает взаимностью лишь одной из них. Однажды судьба разлучает двух влюбленных…Они женятся, и спустя какое-то время она узнает, что ее любимый супруг погиб. Она уезжает в другой город и там вновь выходит замуж. После выясняется, что муж вовсе не погиб, он жив.",
 "f-wd19899057": "Томми Сингх - юный музыкант, завоевавший сердца миллионов поклонников. Он успел обзавестись крупным состоянием и купил большой особняк за миллионы рупий. Однако наркозависимость главного героя играет с ним злую шутку. Очередная доза оказывается для его карьеры роковой: продюсерская компания расторгает с ним контракт и всё начинает катиться под откос. Плюс ко всему прочему, Томми Сингх попадает в тюрьму за незаконное хранение наркотиков. После освобождения из заключения главный герой решает больше никогда не иметь дело с психотропными веществами. Но так ли легко ему будет свернуть с этой дорожки?",
 "f-wd606493": "Наш герой еще совсем молод и полон надежд. Он влюблен в девушку Анну и не знает, что она любит его друга. Когда он узнает об этом, то отчаянию его не будет предела. Но время лечит и у нашего героя еще все впереди.",
 "f-wd23992454": "Бадринатх Бансал – сын крупного деревенского бизнесмена. Он мечтает жениться на хорошей девушке и свить с ней семейное гнёздышко. На свадьбе друга парень встречает строптивую Вайдехи, влюбляется в неё с первого взгляда и сразу же предлагает девушке свою руку и сердце. Однако в планы Вайдехи не входит замужество, и она даёт влюблённому парню от ворот поворот. Но Бадринатх не из тех, кто легко сдаётся. Он решает во что бы то ни стало добиться сердца красавицы.",
 "f-wd402855": "С пыльных страниц истории приходит в нашу жизнь рассказ о небывалой отваге, жестокой гордости и мучительной любви. В далеком прошлом, когда Индия превратилась в колонию Британии, завоеватели взбудоражили страну своей несправедливой политикой «разделяй и властвуй!». Многие славные короли и набобы поддались обманчивым обещаниям и отдали свои плодородные земли и королевства иностранным захватчикам. Исключением стало отважное семейство Прит-хви Сингха, Сыновья Притхви Сингха будут драться до последней капли крови. Самый сильный и смелый - Вир. На кону - его любовь к дочери заклятого врага Мадхавгарха, принцессе Яшодра... На кону - жажда мести за поруганную честь отца... На кону - сама жизнь Вира...",
 "f-wd576941": "Пенджабский парень, живущий в Лондоне, Рикки и девушка из Лахора Алвира от нечего делать в привокзальном кафе в ожидании опаздывающего на два часа поезда знакомятся друг с другом. Рикки пришёл на вокзал встретить свою невесту Анайду, а Алвира своего жениха Стива, но это случайное знакомство круто изменило их жизнь.",
 "f-wd1974609": "Фильм повествует о судьбе молодого парня, которого ещё в детстве бессердечная мать выбросила на улицу. Кто-то из добрых людей подобрал его и вырастил. Но он так и остался сиротой-беспризорником без имени. На вопрос: \"Как тебя зовут?\" - он отвечал так, как ответил на этот вопрос священник: \"Ram Jaane\", что означает в переводе с хинди \"Бог знает\". Как сложилась его жизнь: первая кража, тюрьма, первая безответная любовь, стремление завязать с прошлым... Удалось ли ему выбиться в люди?",
 "f-wd3124318": "Трогательная история о супружеской чете Мальхотра. Они посвятили жизнь, чтобы вырастить четырех сыновей, и как и другие родители рассчитывали, что сыновья станут поддержкой и опорой на старости лет, но на деле все вышло иначе.",
 "f-wd500612": "Разлученные с детства братья-близнецы росли в разных семьях. Один хотел стать певцом, другой же просто дурачил людей на улицах. Но волею судьбы их жизни пересеклись с жизнью двух очаровательных девушек. При встречах с девушками возникает множество комичных ситуаций, ведь братья похожи как две капли воды.",
 "f-wd127129": "Это история об архитекторе Радже Мальхотра. Он патологический неудачник. Будильник не сработал, в душе закончилась вода, сломалась машина по пути на работу, да и клиентами Бог не жалует. Его подруга Хасина утверждает, что он родился под несчастливой звездой и советует ему найти человека, который может изменить его жизнь. Так Радж встречает Прийю — девушку, всегда готовую помочь. После знакомства с Прийей жизнь Раджа резко меняется…",
 "f-wd1659322": "Бесстрашный полковник Арджун и адвокат Гита любят друг друга. После свадьбы Арджун погибает, спасая свою сестру из рук террористов. Не добившись справедливости законным путем, Гита вынуждена организовать побег пятерым заключенным, приговоренным к смертной казни. В обмен на свободу преступники должны помочь совершить возмездие над убийцами возлюбленного Гиты.",
 "f-wd544359": "Это история известного политического дуэта - Ананд - киноактер и Селван - поэт и политик. Соединение их талантов, этот альянс кино и политики, на протяжении многих лет определяли жизнь целого штата. Но все эти политические перипетии, служат лишь фоном, на котором разворачиваются истории их жизни, любви, дружбы и вражды. Их встреча в молодости, в смутные для страны годы борьбы за независимость, изменила не только их жизни. Вдохновение и взаимопонимание положило начало их союзу... под силу ли человеческим слабостям одержать над ним верх?",
 "f-wd692023": "Волею случая старший брат Сиддхартха Джай попадает в бандитскую группировку и главарь банды делает его правой рукой. Однажды Сиддхартх становится невольным свидетелем убийства людьми из этой группировки брата своей подружки. Теперь ему необходимо найти в себе мужество не подчиниться воле брата и включиться в борьбу против бандитов...",
 "f-wd2060167": "Сестра Рахула неожиданно умирает. Теперь ее брату холостяку придется самому вести семейный бизнес, а, так же, взять опеку над тремя детьми. Рахул взявшись за дела, понимает, что семейное дело находится на грани банкротства, да и дети не особо хотят слушать своего дядю. Няни надолго не задерживаются в этом доме, практически каждый день одна сменяет другую. И вот однажды дети сами находят выход из сложной ситуации. А случается этот как раз в тот день, когда они встречают на улице девушку по имени Вайджанти.",
 "f-wd43900": "Эмма живет в Бижапуре вместе с мужем и сыном Бенва. Мужчину, который попытался изнасиловать Эмму, убивает ее муж, семья пытается спастись бегством, но полиция убивает мужа во время погони. Эмма поселяется в небольшой лачуге в трущобах возле Бомбея, где Бенве суждено вырасти, занимаясь чисткой обуви…",
 "f-wd2056955": "Это полицейская история об одной из перевозок опасного преступника из Чандангада в Мумбаи. Злодей Икбал Ансари имеет связи в определенных кругах, поэтому повседневная полицейская миссия перевозки преступника терпит неудачу. Благодаря храбрости одного из офицеров преступнику не удалось бежать, и он был передан «на руки» другому эскорту. Накануне свадьбы дочери полицейский Анант Шривастав по прозвищу «Профессор» получает шанс показать себя в этой миссии, доказать себе и окружающим, что он еще на что-то способен и полностью раскрыть свои способности. Итак, трех офицеров сопровождают также два констебля. Им предстоит научиться работать в команде, потому что пособники Икбала не дремлют и хотят, во что бы то ни стало освободить его...",
 "f-wd21646605": "Золото всегда несет с собой смерть и безумие, в какой бы точке земного шара ни находилось вдруг. Эта история о золотых приисках в штате Карнатака, взятых под контроль некой кучкой влиятельных людей. И о том, что долго такую тайну никто сохранить не может, даже если окружить себя высокими стенами и охраной. Все равно всегда будут те, кто хочет стать новым царем горы. Это случилось в 80-е годы прошлого века, когда родившийся в нищите мальчишка приезжает в тогда еще Бомбей, чтобы стать \"повелителем мира\", как завещала умирающая матушка. Влившись в золотую мафию, он и получает заказ на убийство нынешнего владельца золотых приисков К.Г.Ф. И это - только пролог, сама история еще впереди.",
 "f-wd119205965": "Ноа вынуждена оставить свой город, парня и друзей и переехать в особняк нового богатого мужа своей матери. Там она встречает Ника, своего нового сводного брата. Втайне они безумно влюбляются друг в друга.",
 "f-wd125510637": "История индийской дипломатки, которая оказывается в эпицентре заговора в другой стране.",
 "f-wd3104859": "Велу - простой паренёк-бездельник, всё своё свободное время играющий с друзьями в кабадди. Однажды его команда побеждает на местном матче и попадает в полуфинал, который проходит в Мадурае. Велу не придумывает лучшего способа попасть туда, как свадьба кузины, но планы резко меняются, ведь, приехав туда, Велу почему-то решает спасти незнакомку, которая сбегала от сына министра - Мутупанди...",
 "f-wd63135778": "Недумааран Раджангам «Маара» стремится заставить простого человека летать и в процессе берет на себя самую капиталоемкую промышленность в мире и наживает себе врагов, которые стоят у него на пути к заветной цели.",
 "f-wd108940413": "Вандиятеван отправляется через земли Чола, чтобы доставить послание от наследного принца Адитхи Карикалана, в то время, как верные подданые императора плетут козни против трона...",
 "f-wd124389836": "После вечеринки среди участников театральной труппы, Анджали становится жертвой домогательствы, совершенного одним из мужчин. Назначается встреча, во время которой всплывают новые детали.",
 "f-wd4662712": "Рахул когда-то был очень успешным и популярным музыкантом, но сейчас из-за его постоянных запоев, о карьере и славе можно забыть. Вивек его лучший друг, кроме того выполняет функции его менеджера. Пожалуй, Вивек единственный, кто до сих пор верит в талант Рахула и как-то пытается ему помочь. Однажды сидя в очередном баре Рахул увидел ее – талантливую, красивую исполнительницу Арохи. Рахулу приходит в голову гениальная идея – он решает сделать из нее настоящую звезду",
 "f-wd117842625": "Гуна, офицер полиции в отставке, едет в Великобританию для серьезной операции на головном мозге своей дочери Сане, но там из-за драки с бандитами попадает в тюрьму Уондсворт, где тюремщицей является Сандра Джеймс. Гуна узнает, что трое заключенных, работающих на известного террориста Омара Квадри, планируют сбежать из тюрьмы, чтобы сорвать конференцию G20 в Индии. Гуна разрушает план побега и намеревается помешать Омару Квадри и успеть оплатить операцию дочери...",
 "f-wd19891291": "Четверо друзей отправляются в заброшенный особняк-призрак просто ради забавы, но не подозревают, что возвращаются домой вместе со злобным духом. Спастись от него может оказаться невозможным.",
 "f-wd44612834": "Слепому человеку и так жить непросто, а наш герой умудряется до предела усложнить себе жизнь. Слепой пианист становится, если можно так сказать, свидетелем убийства, что привносит в его жизнь некоторое разнообразие.",
 "f-wd247854": "Сын Заминдара Нарайяна Мукхерджи — Девдас вырос в мире, где богатство ценилось больше человеческой жизни. Его другом детства стала красивая девочка Паро и они весело жили в живописной деревне Тадж Сонапур. Казалось, весь мир существует только для двух детей, но семена страсти уже были посеяны. Мечты Паро были разбиты, когда Девдас уехал на учебу в Лондон.  И вот однажды Девдас вернулся в деревню уже взрослым мужчиной, воспитанным в традициях Запада. Паро все еще любит и ждет его, но разница между ними уже очевидна для всех. Но Девдас, даже понимая эту разницу, не мог устоять перед той, кто из его товарища по детским играм превратилась во взрослую женщину.",
 "f-wd496564": "После разрыва отношений с женатый любовником Су-джин старается забыть прошлое. Однажды она встречает плотника Чхоль-су, который очень хочет стать архитектором. Женщину тянет к нему, парень отвечает взаимностью, и через некоторое время они женятся. Теперь, когда Су-джин думает, что нашла правильного человека, она должна смело встретить свою болезнь, которая заставляет ее терять воспоминания.",
 "f-wd8051196": "Это история отношений двух молодых людей, впервые встретившихся сразу после колледжа. Тогда желание реализовать себя в жизни помешало им быть вместе, но спустя почти десять лет они встречаются снова, уже с багажом реализованных и нереализованных желаний и планов, чтобы испытать счастье любви.",
 "f-wd2009584": "Индийско-пакистанская война, ее самый «горячий» горный рубеж, называемый «линией контроля». Ведь за ним - враги, и отстоять его нужно любой ценой. У каждого из солдат, сражающихся за «линию контроля» своя судьба, но их объединяет то, что каждый оставил в мирной жизни, что-то дорогое сердцу, к чему хочется обязательно вернуться...",
 "f-wd219392": "Это история четырех отцов, четырех дочерей и четырех претендентов стать зятьями и, как предполагает вторая половина названия, они все и являются грязной дюжиной. Каждый из этих отцов хочет, чтобы его дочь вышла замуж за самого богатого наследника. Каждая дочь думает, что она выходит замуж за сына самого богатого человека. Каждый сын притворяется самым богатым наследником. Тем не менее, все эти люди терпеть не могут друг друга, но все они находятся под одной крышей, в одном доме.",
 "f-wd20649274": "Ронни нельзя назвать дураком, но в свои 23 года он своеобразно выражает мысли и решает спорные вопросы. Он мог бы стать отличным врачом или учёным, но бунтарский характер не дает ему такой возможности. Устав от вечных проблем, родители отправляют парня на обучение в академию, где на первом месте стоит дисциплина. Там Ронни сразу проявляет свой бунтарский дух, но возмездие настигло нового студента моментально. Молодой человек понял, что необходимо приспосабливаться, чтобы избежать постоянных унижений, к тому же на горизонте появляется симпатичная девушка с тоже непростым характером.",
 "f-wd370707": "Конец 19-го века. Полная шведских эмигрантов лодка прибывает на датский остров Борнхольм. Среди них Лассе и его сын Пелле. Они находят приют на ферме, но к ним все равно относятся, как к чужакам. Несмотря на это, отец и сын не сдаются в своем стремлении к поиску лучшей жизни.",
 "f-wd19824642": "История взаимоотношений между Карамакате, амазонским шаманом, последним выжившим представителем своего народа, и двумя учеными, которые на протяжении 40 лет вместе ищут на Амазонке священное целебное растение.",
 "f-wd1193433": "Вторая Мировая война закончилась, но Китай все еще слаб и беден. Ип Ман открывает свою школу боевых искусств, однако завоевать свое место под солнцем оказывается непросто — чтобы избежать проблем, Ип Ману нужно сначала завоевать уважение представителей других кунгфу-школ, а председательствующему в их ассоциации Хунгу Ип Ман не понравился с первого взгляда. А тем временем в Гонконге усиливается присутствие британцев, и некоторые из них плевать хотели на китайские традиции и обычаи.",
 "f-wd495134": "19-летняя Ли Гым-джа попадает в тюрьму по ложному обвинению в похищении и убийстве ребёнка. В тюрьме женщина вынашивает план мести и завоевывает сердца заключенных собственной добротой, получив имя Добросердечная госпожа Гым-джа. Отсидев 13 лет, мстительница с помощью тюремных подруг отправляется разыскивать того, кто поломал ей жизнь.",
 "f-wd7572454": "Далекое будущее. Преступная корпорация Гайя стала злейшим врагом Земли, отобрав у людей все: свободу, дом, будущее… Казалось, что надежды на спасение нет… Но, появился Он — космический пират Харлок, капитан призрачного корабля Аркадия. Беглец, готовый сражаться за Землю. Кто Он, герой или преступник?..",
 "f-wd2005041": "Действие фильма разворачивается в послевоенной Японии. Сын мстит за смерть своего отца, высокопоставленного чиновника, который был вынужден совершить самоубийство, беря на себя чужую вину в соответствии с заключенным «Джентльменским соглашением».  Коиши Ниши не удовлетворяется раскрытием деталей этого преступления, а хочет раздавить каждого его участника. Он женится на дочери главы корпорации, ради его уничтожения.",
 "f-wd19702971": "Май 1945 года. Дания постепенно приходит в себя после оккупации и освобождается от господства Германии. Однако все западное побережье все еще заминировано — сюрприз союзным войскам. По решению военного командования, разминирование будет проводиться с помощью военнопленных. Сержанту Расмуссену категорически не везет: в его распоряжение поступают совсем молоденькие немецкие солдаты, мальчишки, еще вчера списывавшие друг у друга на контрольной…",
 "f-wd2296238": "В центре сюжета — влюблённые, не имеющие ни денег, ни пищи, но пытающиеся весело провести свой выходной день. Улицы, дышащие смятением и неустроенностью, безработные и хулиганы, по сути такие же жертвы времени. Любовь и надежда юных влюблённых оберегают их от враждебности окружающего мира.",
 "f-wd195593": "Поль встречает в кафе Мадлен, между ними завязывается разговор — странный и внешне отвлеченный, как всегда бывает у Годара. Поль пишет стихи, увлекается левыми идеями, он интеллектуал и герой своего времени, поэтому остается в меньшинстве. Он только что отслужил в армии и воспринимает гражданку немного свысока. Это «женская», то есть уютная конформистская жизнь, где занимаются шопингом, строят карьеру поп-певицы и хотят походить на персонажей рекламы.",
 "f-wd1144956": "Полиция Гонконга и Китая совместно с Интерполом готовит масштабную операцию по ликвидации интернациональной банды наркоторговцев. Замысел операции сводится к тому, чтобы вытащить из китайской тюрьмы одного из главарей нарко-спрута и через него выйти на верхушку организованной пирамиды.  Кто же сможет осуществить такой дерзкий и рискованный план, если не Суперполицейский. Кевин Ченг, знакомый нам по первым сериям фильма, за какие-то прегрешения, ныне пребывающий в должности постового, вызван для осуществления необычной операции Интерпола. Для поддержки ему назначают директора китайского Интерпола - очаровательную капитаншу Енг.",
 "f-wd572563": "В Кантоне вспыхивает восстание против манчжурской династии Цин. Школьник по имени Сан Те помогает повстанцам. Манчжуры жестоко подавляют восстание, и Сан Те вынужден бежать в храм Шаолинь, где он начинает обучение боевым искусствам, мечтая о мести…",
 "f-wd106371709": "Бездетная пара фермеров проживает в туманной исландской глуши. Однажды одна из их овец приносит загадочное существо, которое супруги забирают в дом и решают растить как собственного ребёнка.",
 "f-wd269326": "История о двух мужчинах, которые становятся друзьями, потому что не желают продаваться, не желают вести жизнь, не отвечающую их чувствам и устремлениям. Джеффри — профессиональный убийца, который, выполняя задание, случайно лишает зрения певицу Дженни.  Между слепой певицей и убийцей возникает взаимная привязанность, но самые близкие отношения у Джеффри завязываются с идущим по его следу полицейским инспектором, который признает в наемном убийце родственную душу.  Джеффри хочет оплатить Дженни операцию по восстановлению зрения, но, чтобы добыть деньги, он должен согласиться на совершение еще одного, последнего, как он надеется, задания.",
 "f-wd425669": "Мари - юная балерина, которая встречает богатого мальчика Хенрика, студента колледжа и влюбляется в него. Через некоторое время с Хенриком происходит несчастный случай - у него повреждения головы и тела, которые приводят к его смерти.\r Много лет спустя Мари размышляет над ошибками, которые она сделала в жизни после смерти своего любимого Хенрика.",
 "f-wd958097": "В эпоху враждующих царств Китай сотрясали междоусобные войны. Самое сильное — Цинь начало покорять другие одно за другим. Однако вражда между теми, что еще оставались непокоренными, не прекращалась. Армии царств Лян и Вэй сошлись в жестокой битве. Столь жестокой, что к ее исходу лишь двое воинов уцелели — молодой благородный полководец, возглавлявший армию Вэй, и простой солдат войска Лян — умудренный жизнью человек, который больше всего на свете не хотел бы именно воевать…Теперь ему выпала редкая удача — он захватывает раненного вражеского военачальника в плен. Если он сумеет доставить пленника своему повелителю — почет, уважение, земельный надел, а главное — возвращение к родному дому ожидают его.",
 "f-wd2296227": "Продолжение похождений отважного дзюдоиста по имени Сугата Сансиро. На этот раз ему предстоит побороть новых соперников, включая белокожего волосатого боксёра, внешне, по мнению японцев, сильно похожего на обезьяну. Но герой сможет побороть всех противников, потому что его сила заключается не в ловкости тела, а в крепости духа.",
 "f-wd20313191": "Вместо прогресса человечество оказалось отброшено назад появлением расы гигантов. Огромные гуманоиды не обладали ни речью, ни разумом, но при этом пожирали людей, как чипсы, а обычное оружие уровня XIX века оказалось бессильно. Остатки рода людского смогли выжить лишь за циклопическими стенами, которые тройным кольцом опоясали последние поля, города и деревни. Затишье продолжалось сто лет, за это время люди успокоились, армия была сокращена, а городская стража превратилась в дармоедов. Боеспособность сохранил лишь Разведкорпус — но кому нужны самоубийцы, что постоянно рискуют жизнью за стенами, когда можно спокойно сидеть за каменным забором?",
 "f-wd51743": "Два клоуна, живущие во времена династии Чосон, арестованы за то, что показывали сатирическое представление, которое высмеивало короля. Их привозят в королевский дворец, над ними нависает угроза казни, но им дается шанс спастись, если они смогут рассмешить короля.  Главный герой, клоун Гон Киль, хоть и мужчина, но завоевал сердце короля своей необычайной женской красотой. Ревнивая королева всякий раз пыталась унизить его, даже задумала убить его.",
 "f-wd428617": "Целомудренная девушка для дьявола, в буквальном смысле, что бельмо на глазу. Чтобы избавить себя от этой напасти, властитель ада призывает Дон Жуана. Великий грешник должен соблазнить 20-летнюю дочь пастора, очаровательную Бритт-Мари прежде, чем она выйдет замуж и потеряет девственность. В распоряжении распутника всего лишь день и ночь…",
 "f-wd224985": "Отто и Ана знакомятся ещё детьми. Их имена - палиндромы. Они - две части одного целого, нашедшие друг друга в результате цепочки случайностей. С момента этой встречи их жизни неотделимы друг от друга. Они верят, что начался длинный круговорот жизни, который однажды замкнется где-то за Полярным кругом.  Там, за  Полярным кругом, есть только незаходящее Солнце и вечная Любовь.",
 "f-wd2290980": "Ян-Эрик Видгрен — ученик старших классов в средней шведской школе, в которой все боятся преподавателя латыни с характерной кличкой Калигула. Ян-Эрик встречается с девушкой Бертой, работающей в табачной конторе и влюбляется в неё. Однажды она сознаётся, что её преследует один садист, но умалчивает, что это — Калигула.",
 "f-wd19372190": "Сигнал тревоги разносится над спящим городом. То, чего так боялись сейсмологи, сбылось — сильнейший тектонический сдвиг вызывает обрушение горного массива. Теперь гигантское смертоносное цунами движется прямо на людей. Опытный геолог Кристиан Айкорд оказывается в эпицентре самого страшного кошмара своей жизни.",
 "f-wd389303": "Землетрясение в городе Таншане (провинция Хэбэй) 1976 года длилось меньше чем полминуты, но унесло несколько сотен тысяч жизней. Эти секунды поставили мать перед невозможным выбором — спасти сына или дочь, и спасение обернулось грузом вины на десятилетия.",
 "f-wd677987": "Прошел год после битвы Годзиллы с Механической Годзиллой. И вот новое предупреждение: японцы должны вернуть океану все, что они сохранили от первого нашествия Годзиллы. И кости, и органические ткани, — абсолютно все, вплоть до молекул ДНК, необходимо отправить в бездну вод, чтобы получить шанс на спокойную жизнь.  Предупреждение это исходит от другого легендарного монстра — от Мотры, которая всегда была лютым врагом Годзиллы. И Годзилла не заставляет себя долго ждать: чудовище выходит из моря, чтобы сразиться с Мотрой и с Меха-Годзиллой…",
 "f-wd1331978": "В детстве Ичи обижали сверстники. Поэтому он вырос полным психом: убил родителей и попал под влияние босса одной из мощнейших преступных группировок, который использовал парня для устранения конкурентов. Но однажды сам босс внезапно исчезает, причем не один, а с солидным чемоданом, набитым деньгами. Вскоре в одном из отелей находят его труп в луже крови и вывернутыми наизнанку органами. Его ближайшие друзья пытаются найти убийцу и подвергнуть его не менее страшной смерти. Правда они не знают, что убийца буквально дышит им в спину, работая вместе с ними над этим убийством. Ведь это сам Ичи: Как бы медленно не проходило расследование, но круг подозреваемых сужается и скоро вся жизнь Ичи повернет свое «привычное» русло…",
 "f-wd1214152": "Вся деревня знает, что Машти Хассан любит свою корову до смерти. Однажды он отправляется в Тегеран, а его корова умирает. Зная какие отношения у Хассана с коровой, по его возвращении односельчане говорят ему, что корова убежала.",
 "f-wd1559662": "История жизни, «преступлений» и искупления Йосты Берлинга, лишенного сана пастора, шведского донжуана поневоле.",
 "f-wd384243": "Женщина возвращается после долгих лет отсутствия на юбилей матушки. Она уже не боится старого дома, странных отношений между местными жителями. Фильм как бы подводит итог скрупулезному метафорически-поэтическому исследованию режиссёром последствий франкизма.",
 "f-wd7918377": "Трое незадачливых воришек попадают в заколдованный город, где на протяжении веков правят бал коварные ведьмы. Задача героев проста — унести ноги из страшного места. Для этого надо постараться не влюбиться в обитательниц этого гиблого места… Сюжет основан на подлинной истории, которая случилась здесь в начале XVII века, когда одна из жительниц деревни заявила, что она ведьма и регулярно участвует в шабашах в близлежащих пещерах со своими соседками. Тогда Святая Инквизиция арестовала почти всё население Сугаррамурди и окрестных сёл (около 300 человек), устроив суд по делу «Ведьминской деревни», который длился два года. В результате в 1610 году 40 жителей деревни были обвинены в колдовстве, а 11 из них — сожжены на костре. С тех пор Сугаррамурди запечатлелся в коллективной памяти как обиталище ведьм.",
 "f-wd1464924": "Городской бизнесмен Юшенг возвращается в родную деревню в Северном Китае на похороны своего отца, сельского учителя. Мать Луо во время похорон хочет соблюсти все древние обычаи, невзирая на то, что времена изменились и люди живут по-новому. Однако Юшенг считает, что мнение родительницы надо уважать, и решает выполнить все её пожелания. В день похорон на кладбище собирается сотня учеников покойного учителя, и тут Юшенг вспоминает об самом заветном желании отца — тот хотел, чтобы сын учил детей в сельской школе. Перед своим возвращением в город Юшенг решает попробовать себя в роли школьного учителя.",
 "f-wd787091": "Вторая часть фильма рассказывает о том, как бывший гангстер Хо, выйдя из тюрьмы, при помощи своего брата-полицейского Кита внедряется в банду фальшивомонетчиков.  Когда жизни ее главаря Лунга начинает грозить опасность, братья переправляют его в Нью-Йорк под защиту своего друга и брата-близнеца Марка Гора — Кена. Спасая Лунга, Кен бесстрашно сражается с наемными убийцами, подосланными мафией. И следуя чувству долга, он оставляет свои дела и отправляется в Гонконг, чтобы вместе друзьями разобраться с бандитами на месте.",
 "f-wd24113685": "Продавец автомобилей Ли Джон-су возвращался домой после удачной сделки. В его машине был торт на день рождения любимой дочки, две бутылки воды и телефон, заряженный на три четверти, когда горный тоннель, по которому ехал наш герой, застонал, вздрогнул и обрушился. Погребенный под десятками тонн бетона и горной породы, Ли Джон-су был уверен, что его спасение — вопрос нескольких часов. Ли Джон-су ошибался.",
 "f-wd682574": "Копенгаген, 1944 год. Дания оккупирована немецкими войсками. Борцы Сопротивления Пламя и Цитрон работают под прикрытием, ликвидируя датских информаторов и занимаясь саботажем. Их объединяет ненависть к врагам свободы, но юный идеалист Пламя мечтает открыто выступить с оружием против захватчиков, а более чуткий Цитрон все больше втягивается в политические интриги.",
 "f-wd7741216": "В пригороде Стокгольма в раздевалке спортивного клуба найден зверски убитый мужчина. Позже в его доме обнаруживают зарубленных с чудовищной жестокостью жену и маленькую дочь. Похоже, убийца задался целью вырезать всю семью, однако тяжело раненный сын выжил. Комиссар уголовной полиции Йона Линна узнает, что в живых остался еще один член семьи — старшая сестра мальчика. Он понимает: необходимо найти девушку до того, как это сделает убийца. Чтобы поскорее допросить единственного свидетеля, Иона Линна связывается с врачом Эриком Марией Барком и убеждает его загипнотизировать мальчика. Только так можно получить описание преступника. Эрик нарушает свое давнее обещание отказаться от занятий гипнозом. И цепочка невероятных событий начинает неумолимо разматываться…",
 "f-wd125856483": "Известную актрису Элизабет срывает с репетиции тревожный звонок из школы, где учится её шестилетний сын Арман. В пустых классах разворачивается зловещее противостояние, но о детях быстро забывают — ведь у взрослых есть свои тайны и желания, а в огласке не заинтересован никто. Элизабет предстоит добиться правды и не дать одержимости и зависти разрушить жизнь её семьи.",
 "f-wd2739665": "Фильм о японской семье, родителях и детях, традициях и их медленном, но неотвратимом разрушении.",
 "f-wd656966": "Sha, Po, Lang — звезды, чье положительное или отрицательное влияние восточные астрологи определяют, исходя из их взаимного расположения… Как встанут эти светила сейчас?  Детектив Чан заботится о дочери убитого свидетеля, мечтая отомстить убийце, «королю» мафии По. Чан так сильно жаждет мести, что в его душе стирается грань между добром и злом. В роковое противостояние оказывается невольно вовлечен и Ма, начальник ОБОП. Теперь все трое — участники смертельного поединка…",
 "f-wd20870852": "Случайно найденное письмо подталкивает героиню Кларенс отправиться на поиски тех мест, где ее отец Джеймс и дядя Килиан провели большую часть своей молодости, на остров Фернандо-По. В недрах этих пышных и соблазнительных земель, девушка раскапывает тайны истории запретной любви, обернутой бурными историческими обстоятельствами, последствия которых привели к нынешней ситуации…",
 "f-wd2276999": "Деревенский мальчик поступает в услужение к капризной любовнице могущественного главаря одной из шанхайских триад. История ребенка в безжалостном мире, история о пробуждении души и ее гибели. Гангстерская история. Человеческая драма.",
 "f-wd594882": "Лин Сяою, мастер китайских боевых искусств, получает задание от Анны Вильямс из корпорации G, находящейся под командованием Казуи Мисима. Задача Лин состоит в том, чтобы проникнуть в качестве шпиона в Киотскую международную школу и найти студента по имени Син Камия. Однако Син совершает самоубийство по неизвестной причине, и раcследование Сяою заходит в тупик. После этого Лин встречает таинственную девушку по имени Алиса, и они продолжают расследование вместе. Они узнают, что Син, вероятно, был кем-то похищен. Сяою хочет спасти Сина, для этого она начинает самостоятельное расследование, но она попадает в огромные владения корпорации Мисима Заибацу, которые скрывают тайные родственные заговоры с участием членов семьи Мисима — Дзина Казама, Казуи Мисима и вероятнее всего скончавшегося Хейхати Мисима.",
 "f-wd1235519": "История запретной любви молодого Сюсена и Паньянь, девушки-змеи. В детстве у Сюсена был друг — красивая белая змейка, но суеверные сельчане заставили мальчика прогнать её. Спустя годы Белая Змея, оказавшаяся демоном, вернулась в город в облике прекрасной девушки Паньянь. Сюсен полюбил её с первого взгляда.",
 "f-wd494364": "В море на барже живут 60-летний мужчина и 16-летняя девушка, которую он взял на воспитание еще ребенком. Она обладает таинственным даром предсказывать судьбу. Мужчина заботится о девушке: одевает, кормит, купает. Он безумно в нее влюблен и уверен, что это чувство взаимно, до свадьбы осталось несколько месяцев. Появление на барже молодого человека, в которого влюбляется девушка, разрушает размеренную жизнь героев…",
 "f-wd110629546": "Из-за изменений климата Земля почти вымерла и стала непригодной для жизни, а в убежище, где ютятся остатки человечества, разразилась война. Шанс на выживание в бойне всего один — оживить легендарную воительницу, перенеся её сознание в тело робота, предварительно проведя эксперимент по клонированию мозга. Проект по «воскрешению» своей матери возглавляет женщина-учёный из лаборатории по изучению искусственного интеллекта. За успех эксперимента несут ответственность Со Хён, руководитель группы лаборатории, разрабатывающей технологии клонирования мозга и искусственного интеллекта и Сан Хун, директор лаборатории.",
 "f-wd1126097": "Освободившись после очередной отсидки, Тони узнает, что у него есть ребенок. Он отчаянно пытается поправить свое положение и свой имидж неудачника. Он хочет завоевать уважение своего отца, самого злобного гангстера Копенгагена, которому он должен денег. Но как он ни старается, из-за его непреодолимой тупости дела становятся все хуже и хуже. Единственное, что действительно идет в гору — его плохая репутация. А его отец делает окончательный вывод, что Тони — бесполезный и нежелательный человек. Особенно после того, как тот, желая угодить папаше, стащил новенькую «Феррари», оборудованную радиомаяком, и пригнал ее к отцовскому дому. Среди наркотиков и фени, продажной любви и бессмысленного насилия, все больше теряя голову, Тони отчаянно пытается устроиться в блатном мире.",
 "f-wd232003": "Торговец оружием Йолаф Петерсон собирается провернуть сделку с партизаном Монго. Однако деньги Монго заперты в банке, а комбинацию от сейфа знает лишь профессор Ксантос, находящийся под стражей у американцев. Йолаф соглашается освободить Ксантоса и в сопровождении лейтенанта Васко отправляется в стан американского флота.",
 "f-wd213138": "Герой фильма — скромный китайский ремесленник-изготовитель бумаги, живущий в далекой деревне с женой и двумя детьми во времена империи Цин. Однажды в деревне неожиданно появляется сыщик, и в их безмятежной жизни происходит переворот…",
 "f-wd63213933": "Чжоу Цзэнун — лидер небольшой банды, которая занимается кражей мотоциклов. Во время одной из разборок он случайно убивает полицейского и становится целью номер один для полиции и властей. В бегах Чжоу встретит проститутку Лю Айай — оба загнаны в тупик и ищут выход."
};
